/* Current-DBA workflow using the existing ephemeris and boundary solver. */
(()=>{'use strict';const $=id=>document.getElementById(id);let results=[],version=0;
function current(){for(const [id,value]of [['tr-dba-selection-source','current'],['tr-date-range-source','period'],['tr-period','PD'],['tr-dasha-source','auto'],['tr-direction','all']])if($(id))$(id).value=value;KPTransitSelection.sync();KPTransit.refresh();return KPTransit.currentPeriods();}
function sunTracks(data){const pairs=[['MD','AD','PD'],['MD','PD','AD'],['AD','MD','PD'],['AD','PD','MD'],['PD','MD','AD'],['PD','AD','MD']];return pairs.map(order=>{const lords=order.map(k=>data.periods[k].id),natal=$('tr-zone').value==='natal',points=lords.map(id=>currentKPModel.planets.find(p=>p.id===id));return {id:'sun:'+order.join('-'),planet:'Su',label:'Sun · '+order.map((k,i)=>k+' '+lords[i]+' '+['sign','star','sub'][i]).join(' + '),levels:['sign','star','sub'],test:p=>natal?p.signIndex===points[0].signIndex&&p.nakIndex===points[1].nakIndex&&p.nakIndex===points[2].nakIndex&&p.sl===points[2].sl:p.sgl===lords[0]&&p.stl===lords[1]&&p.sl===lords[2]};});}
function draw(){const tbody=$('tr-result-rows');tbody.replaceChildren();for(const row of results){const tr=document.createElement('tr');tr.dataset.track=row.trackId;tr.dataset.entry=row.start;tr.dataset.exit=row.end;for(const value of [row.planet,row.label,row.start,row.end]){const td=document.createElement('td');td.textContent=value;tr.append(td);}tbody.append(tr);}if(!results.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=4;td.textContent='No matching intervals in the current MD / AD / PD window.';tr.append(td);tbody.append(tr);}}
async function run(){const token=++version;results=[];KPTransit.cancel();try{const data=current(),pd=data.periods.PD,start=new Date(Math.max(Date.now(),Date.parse(pd.startUTC))),end=new Date(pd.endUTC),mode=$('tr-mode').value,tracks=mode==='sun'?sunTracks(data):KPTransit.makeTracks(data);let periods=null;if(mode==='event'){const required=$('tr-houses').value.split(/[,\s]+/).filter(Boolean).map(Number);periods=KPEventOutcome.periodMatches(currentKPModel,{method:$('tr-significator-method').value},{start,end},required);if(!periods.length){draw();$('tr-status').textContent='Current MD, AD and PD do not jointly support the selected event houses. No supported date found in this PD.';return;}}
$('tr-status').dataset.state='running';$('tr-run').disabled=true;$('tr-cancel').hidden=false;let found=await KPTransit.scan({start,end,tracks,shouldCancel:()=>token!==version,onProgress:p=>{if(token===version)$('tr-status').textContent='Searching current MD / AD / PD… '+Math.round(p*100)+'%';}});if(token!==version)return;if(periods)found=KPEventOutcome.intersect(found,periods);results=found;draw();$('tr-status').dataset.state='complete';$('tr-status').textContent=results.length+' matching transit intervals · current MD '+data.periods.MD.id+' / AD '+data.periods.AD.id+' / PD '+pd.id+' · upcoming dates only. Entry is a transit boundary, not a guaranteed event date.';
}catch(e){if(token===version){$('tr-status').dataset.state='error';$('tr-status').textContent=e.message;}}finally{if(token===version){$('tr-run').disabled=false;$('tr-cancel').hidden=true;if($('tr-status').dataset.state==='running')$('tr-status').dataset.state='complete';}}}
function cancel(){version++;$('tr-status').dataset.state='idle';$('tr-status').textContent='Search cancelled.';$('tr-run').disabled=false;$('tr-cancel').hidden=true;}
function init(){document.querySelectorAll('#tr-planet-options input').forEach(n=>n.checked=true);const section=$('transit');section.classList.add('kp-current-dba-only');document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.id==='tr-run'){event.preventDefault();event.stopImmediatePropagation();run();}else if(button.id==='tr-cancel'){event.preventDefault();event.stopImmediatePropagation();cancel();}else if(button.dataset.trSearchMode){event.preventDefault();event.stopImmediatePropagation();KPHandyTransits.mode(button.dataset.trSearchMode);run();}else if(button.id==='transit-preview'){event.preventDefault();event.stopImmediatePropagation();const table=section.querySelector('.tr-result-mount');KPChartWorkspace.printable('Transit dates · current MD / AD / PD','<p>'+ $('tr-status').textContent+'</p>'+table.outerHTML);}else if(button.dataset.tab==='transit'||button.dataset.quickFunction==='transit'){setTimeout(()=>{try{current();}catch(e){$('tr-status').textContent=e.message;}},0);}},true);section.addEventListener('change',()=>{version++;results=[];},true);window.addEventListener('chart-manual-change',()=>{version++;results=[];});try{current();}catch(_){} }
window.KPTransitWorkspace=Object.freeze({run,cancel,getResults:()=>results.map(r=>({...r})),sunTracks,current});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,200));else init();})();
